-- Retira únicamente las demostraciones anteriores que no tienen actividad.
UPDATE subasta_lotes l
SET estado='CANCELADA', version=version+1
WHERE (l.semilla ~ '^demo-[0-9]+-[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    OR l.semilla ~ '^remata-[a-z]+-[0-9]{4}-[0-9]{2}-[0-9]{2}$')
  AND l.estado IN ('PROGRAMADA','ACTIVA') AND l.pujas=0 AND l.ganador_id IS NULL
  AND NOT EXISTS (SELECT 1 FROM subasta_pujas p WHERE p.lote_id=l.id)
  AND NOT EXISTS (SELECT 1 FROM subasta_ordenes o WHERE o.lote_id=l.id);

INSERT INTO subasta_lotes (semilla,titulo,descripcion,categoria,condicion,atributos,imagenes,
 precio_inicial,incremento,precio_actual,tienda_email,estado,inicio,fin)
